import unittest
from app import choose_value

class ChoiceTest(unittest.TestCase):
    def test_present_override(self):
        self.assertEqual(choose_value("port", {"port": 8080}, {"port": 80}), 8080)

    def test_absent_override(self):
        self.assertEqual(choose_value("port", {}, {"port": 80}), 80)

    def test_false_override(self):
        self.assertIs(choose_value("enabled", {"enabled": False}, {"enabled": True}), False)
